const { IoTClient, CreatePolicyCommand } = require("@aws-sdk/client-iot");
const response = require('cfn-response');
exports.handler = async function(event, context) {
    console.log("REQUEST RECEIVED:\n" + JSON.stringify(event));
    if (event.RequestType == "Delete") {
        await sendResponse(event, context, response.SUCCESS, {});
        return;
    }
    const policyName = "device-onboarding";
    const region = process.env.AWS_REGION;
    const awsAccountId = context.invokedFunctionArn.split(':')[4];
    const policyDocument = `{
        "Version": "2012-10-17",
        "Statement": [
        {
            "Effect": "Allow",
            "Action": [
            "iot:Connect"
            ],
            "Resource": [
            "arn:aws:iot:${region}:${awsAccountId}:client/\${iot:Connection.Thing.ThingName}"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
            "iot:Publish",
            "iot:Receive"
            ],
            "Resource": [
            "arn:aws:iot:${region}:${awsAccountId}:topic/\${iot:Connection.Thing.ThingName}/*"
            ]
        },
        {
            "Effect": "Allow",
            "Action": [
            "iot:Subscribe"
            ],
            "Resource": [
            "arn:aws:iot:${region}:${awsAccountId}:topicfilter/\${iot:Connection.Thing.ThingName}/*"
            ]
        }
        ]
    }`;
    console.log("Policy document:\n", policyDocument);
    const iot = new IoTClient();
    try {
        const data = await iot.send(new CreatePolicyCommand({policyName, policyDocument}));
        const responseData = { policyName: data.policyName };
        console.log('Response data: ' + JSON.stringify(responseData));
        await sendResponse(event, context, response.SUCCESS, responseData);
    } catch (err) {
        const responseData = { Error: "createIoTPolicy call failed" };
        console.error(responseData.Error + ":\n", err);
        await sendResponse(event, context, response.FAILED, responseData);
    }
};
// Wrap cfn-response's callback-based send so it can be awaited in the async handler.
function sendResponse(event, context, status, data) {
    return new Promise(function(resolve) {
        const done = context.done;
        context.done = function() {
            resolve();
            if (done) {
                done.apply(context, arguments);
            }
        };
        response.send(event, context, status, data);
    });
}

